60	async function ownedServer(serverId: string) {
61	  const user = await requireUser();
62	  const server = await db.server.findUnique({
63	    where: { id: serverId },
64	    select: {
65	      id: true,
66	      userId: true,
67	      status: true,
68	      hostname: true,
69	      rootPassword: true,
70	      rootPasswordEnc: true,
71	      sshPort: true,
72	      dedicatedIp: { select: { address: true } },
73	      osTemplate: { select: { family: true } },
74	      gamePlan: { select: { gameFamily: true } },
75	    },
76	  });
77	  if (!server) throw new Error("Not found");
78	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
79	  return { user, server };
80	}
