82	/** Resolve the game family (game plan first, then OS template) if it is a game. */
83	function resolveFamily(server: {
84	  osTemplate?: { family?: string | null } | null;
85	  gamePlan?: { gameFamily?: string | null } | null;
86	}): string | null {
87	  const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
88	  return isGameFamily(fam) ? fam : null;
89	}
