91	function requireSpec(server: Parameters<typeof resolveFamily>[0]): GameControlSpec {
92	  const family = resolveFamily(server);
93	  const spec = controlSpec(family);
94	  if (!spec) throw new Error("This server is not a supported game server.");
95	  return spec;
96	}
