62	function fmtUptime(seconds: number): string {
63	  if (!seconds || seconds <= 0) return "—";
64	  const d = Math.floor(seconds / 86400);
65	  const h = Math.floor((seconds % 86400) / 3600);
66	  const m = Math.floor((seconds % 3600) / 60);
67	  return d > 0 ? `${d}d ${h}h ${m}m` : h > 0 ? `${h}h ${m}m` : `${m}m`;
68	}
