"use client";

import { useEffect, useState, useTransition } from "react";
import {
  getPublicListingState,
  togglePublicListing,
  updatePublicDescription,
} from "@/lib/actions-game-control";

/**
 * Public Directory card — lets the server owner toggle whether their server
 * appears in the public directory at /game-servers/directory and edit the
 * description shown there. Lives in the game-panel Settings tab.
 */
export function GamePublicListing({
  serverId,
  connectAddress,
}: {
  serverId: string;
  /** The subdomain or ip:port shown to the owner — used in the preview. */
  connectAddress: string | null;
}) {
  const [enabled, setEnabled] = useState(false);
  const [description, setDescription] = useState("");
  const [savedDesc, setSavedDesc] = useState("");
  const [loaded, setLoaded] = useState(false);
  const [pending, startTransition] = useTransition();
  const [msg, setMsg] = useState<{ text: string; ok: boolean } | null>(null);

  useEffect(() => {
    let alive = true;
    getPublicListingState(serverId).then((r) => {
      if (!alive) return;
      if (r.ok) {
        setEnabled(r.publicListing);
        setDescription(r.publicDescription ?? "");
        setSavedDesc(r.publicDescription ?? "");
      }
      setLoaded(true);
    });
    return () => { alive = false; };
  }, [serverId]);

  function handleToggle() {
    const next = !enabled;
    setEnabled(next);
    setMsg(null);
    startTransition(async () => {
      const r = await togglePublicListing(serverId, next);
      if (!r.ok) {
        setEnabled(!next);
        setMsg({ text: r.error, ok: false });
      } else {
        setMsg({ text: next ? "Listed in directory." : "Removed from directory.", ok: true });
      }
    });
  }

  function handleSaveDescription() {
    setMsg(null);
    startTransition(async () => {
      const r = await updatePublicDescription(serverId, description);
      if (!r.ok) {
        setMsg({ text: r.error, ok: false });
      } else {
        setSavedDesc(description.trim().slice(0, 500));
        setMsg({ text: "Description saved.", ok: true });
      }
    });
  }

  if (!loaded) {
    return (
      <div className="card animate-pulse">
        <div className="h-5 w-40 rounded bg-white/[0.06]" />
        <div className="mt-3 h-4 w-64 rounded bg-white/[0.04]" />
      </div>
    );
  }

  const descDirty = description.trim() !== savedDesc;

  return (
    <div className="card">
      <div className="flex items-center justify-between">
        <div>
          <h3 className="font-semibold">Public Directory</h3>
          <p className="mt-1 text-sm text-slate-400">
            List your server in the{" "}
            <a href="/game-servers/directory" target="_blank" className="text-brand-300 hover:text-brand-200 underline">
              public server directory
            </a>{" "}
            so other players can find and join it.
          </p>
        </div>
        {/* Toggle switch */}
        <button
          type="button"
          role="switch"
          aria-checked={enabled}
          disabled={pending}
          onClick={handleToggle}
          className={`relative inline-flex h-6 w-11 flex-shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-colors duration-200 ease-in-out focus:outline-none focus:ring-2 focus:ring-brand-500 focus:ring-offset-2 focus:ring-offset-navy-900 disabled:opacity-50 ${
            enabled ? "bg-brand-500" : "bg-white/[0.12]"
          }`}
        >
          <span
            className={`pointer-events-none inline-block h-5 w-5 transform rounded-full bg-white shadow ring-0 transition duration-200 ease-in-out ${
              enabled ? "translate-x-5" : "translate-x-0"
            }`}
          />
        </button>
      </div>

      {enabled && (
        <div className="mt-5 space-y-4 border-t border-white/[0.06] pt-5">
          {/* Description textarea */}
          <div>
            <label htmlFor="pub-desc" className="block text-sm font-medium text-slate-300">
              Public description
            </label>
            <p className="mt-1 text-xs text-slate-500">
              Tell players what your server is about. Max 500 characters.
            </p>
            <textarea
              id="pub-desc"
              value={description}
              onChange={(e) => setDescription(e.target.value.slice(0, 500))}
              rows={3}
              maxLength={500}
              placeholder="A friendly survival server with weekly events..."
              className="mt-2 w-full rounded-xl border border-white/[0.08] bg-navy-950/60 px-3 py-2.5 text-sm text-slate-200 placeholder:text-slate-600 focus:border-brand-500/40 focus:outline-none focus:ring-1 focus:ring-brand-500/30"
            />
            <div className="mt-1 flex items-center justify-between">
              <span className="text-xs text-slate-500">{description.length}/500</span>
              <button
                type="button"
                disabled={pending || !descDirty}
                onClick={handleSaveDescription}
                className="rounded-lg bg-brand-500/20 px-3 py-1.5 text-xs font-medium text-brand-200 transition hover:bg-brand-500/30 disabled:opacity-40"
              >
                {pending ? "Saving..." : "Save description"}
              </button>
            </div>
          </div>

          {/* Preview card */}
          <div>
            <p className="mb-2 text-xs font-semibold uppercase tracking-wide text-slate-500">
              Directory preview
            </p>
            <div className="rounded-2xl border border-white/[0.07] bg-navy-900/50 p-4">
              <div className="flex items-start justify-between gap-3">
                <div className="min-w-0 flex-1">
                  <div className="flex items-center gap-2">
                    <span className="inline-block h-2 w-2 rounded-full bg-emerald-400" />
                    <span className="font-semibold text-white truncate">Your Server</span>
                  </div>
                  {description.trim() ? (
                    <p className="mt-2 text-sm text-slate-400 line-clamp-2">{description.trim()}</p>
                  ) : (
                    <p className="mt-2 text-sm italic text-slate-600">No description yet</p>
                  )}
                </div>
              </div>
              <div className="mt-3 flex items-center gap-3 text-xs text-slate-500">
                <span className="font-mono">{connectAddress ?? "play.nxeon.cloud"}</span>
                <span className="rounded-full border border-white/10 bg-white/[0.04] px-2 py-0.5 text-[10px] font-medium text-slate-400">
                  Minecraft
                </span>
              </div>
            </div>
          </div>
        </div>
      )}

      {msg && (
        <p className={`mt-3 text-xs ${msg.ok ? "text-emerald-400" : "text-red-400"}`}>
          {msg.text}
        </p>
      )}
    </div>
  );
}

