import type { Metadata } from "next";
import { db } from "@/lib/db";
import { gameSubdomainBase } from "@/lib/game-subdomain-dns";
import { AmbientField } from "@/components/marketing/AmbientField";
import { Section, SectionTitle } from "@/components/marketing/primitives";
import { CtaBand } from "@/components/marketing/sections";
import { Reveal } from "@/components/marketing/Reveal";
import { ServerDirectoryList } from "./DirectoryList";

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Public Minecraft Servers | Nxeon",
  description:
    "Browse community Minecraft servers hosted on Nxeon. Find survival, creative, SkyBlock and modded servers to join instantly — copy the address and connect.",
  alternates: { canonical: "/game-servers/directory" },
  openGraph: {
    title: "Public Minecraft Servers | Nxeon",
    description: "Find and join community Minecraft servers hosted on Nxeon.",
    type: "website",
  },
};

/** Shared shape passed to the client list component. No internal IDs, IPs, or owner info. */
export type DirectoryServer = {
  /** Opaque key for React — not the real server ID. */
  key: string;
  name: string;
  description: string | null;
  /** player slots (max) */
  maxPlayers: number | null;
  /** connect address — subdomain preferred, never raw IP */
  connectAddress: string;
  /** e.g. "Minecraft", "Minecraft Bedrock" */
  gameLabel: string;
  /** e.g. "minecraft", "bedrock" */
  gameFamily: string;
  /** game variant if known, e.g. "Paper", "Fabric" */
  variant: string | null;
  /** Whether this is a free-tier server */
  isFree: boolean;
};

export default async function DirectoryPage() {
  const subdomainBase = await gameSubdomainBase();

  // ── Paid game servers with publicListing=true ──
  const paidServers = await db.server.findMany({
    where: {
      publicListing: true,
      status: "RUNNING",
      gamePlan: { isNot: null },
    },
    select: {
      id: true,
      name: true,
      label: true,
      publicDescription: true,
      subdomain: true,
      gamePlan: { select: { slots: true, gameFamily: true, name: true } },
      osTemplate: { select: { name: true, family: true } },
    },
    orderBy: { createdAt: "asc" },
  });

  // ── Free Minecraft servers with isPublic=true ──
  const freeServers = await db.freeMinecraftServer.findMany({
    where: {
      isPublic: true,
      status: "READY",
    },
    select: {
      id: true,
      name: true,
      subdomain: true,
      publicTagline: true,
      publicDescription: true,
      activeGameType: true,
      activeGameMode: true,
    },
    orderBy: { createdAt: "asc" },
  });

  // ── Merge into a unified, privacy-safe list ──
  const servers: DirectoryServer[] = [];

  for (const s of paidServers) {
    // Only show servers with a subdomain — never expose raw IP
    const connectAddress = s.subdomain
      ? `${s.subdomain}.${subdomainBase}`
      : null;
    if (!connectAddress) continue;

    const family = s.gamePlan?.gameFamily ?? s.osTemplate?.family ?? "minecraft";
    const gameLabel =
      family === "bedrock" ? "Minecraft Bedrock" :
      family === "minecraft" ? "Minecraft" :
      (s.gamePlan?.name?.split("—")[0]?.trim() ?? family.charAt(0).toUpperCase() + family.slice(1));

    servers.push({
      key: `p-${s.id.slice(0, 8)}`,
      name: s.label || s.name,
      description: s.publicDescription,
      maxPlayers: s.gamePlan?.slots ?? null,
      connectAddress,
      gameLabel,
      gameFamily: family,
      variant: null,
      isFree: false,
    });
  }

  for (const s of freeServers) {
    const connectAddress = `${s.subdomain}.${subdomainBase}`;
    const typeLabel = s.activeGameType === "vanilla"
      ? ""
      : ` ${s.activeGameType.charAt(0).toUpperCase() + s.activeGameType.slice(1)}`;

    servers.push({
      key: `f-${s.id.slice(0, 8)}`,
      name: s.name || s.subdomain,
      description: s.publicDescription || s.publicTagline || null,
      maxPlayers: null,
      connectAddress,
      gameLabel: `Minecraft${typeLabel}`,
      gameFamily: "minecraft",
      variant: s.activeGameType !== "vanilla" ? s.activeGameType : null,
      isFree: true,
    });
  }

  // Sort: paid first, then by name
  servers.sort((a, b) => {
    if (a.isFree !== b.isFree) return a.isFree ? 1 : -1;
    return a.name.localeCompare(b.name);
  });

  return (
    <div className="relative min-h-screen overflow-hidden">
      <div aria-hidden className="pointer-events-none absolute inset-0 z-0">
        <AmbientField />
        <div className="absolute inset-0 bg-[radial-gradient(ellipse_70%_50%_at_15%_-5%,rgba(111,71,245,0.14),transparent_60%),radial-gradient(ellipse_60%_45%_at_95%_0%,rgba(59,130,246,0.10),transparent_60%)]" />
      </div>

      <div className="relative z-10">
        {/* Hero */}
        <section className="mx-auto max-w-7xl px-4 pb-6 pt-10 sm:px-6 sm:pt-20 lg:px-8">
          <Reveal>
            <div className="mx-auto max-w-3xl text-center">
              <span className="eyebrow-pill mb-5">
                <span aria-hidden>🌍</span> Server Directory
              </span>
              <h1 className="text-4xl font-black leading-[1.05] tracking-tight text-white sm:text-5xl">
                Public Minecraft Servers
              </h1>
              <p className="mx-auto mt-5 max-w-xl text-lg text-slate-300">
                Browse community servers hosted on Nxeon. Find your next world, copy the
                address, and start playing.
              </p>
            </div>
          </Reveal>
        </section>

        {/* Server list */}
        <Section tone="base" size="lg">
          <ServerDirectoryList servers={servers} />
        </Section>

        {/* CTA */}
        <Section tone="deep" size="lg">
          <CtaBand
            title={<>Host your own server for <span className="grad-text">free</span></>}
            sub="Get a free Minecraft server with your own subdomain, mod menu, and full control panel. List it here for others to find."
            primary={{ label: "Get your free server", href: "/free-minecraft-hosting" }}
            secondary={{ label: "See all game plans", href: "/game-servers" }}
          />
        </Section>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import type { DirectoryServer } from "./page";

/**
 * Client-side server list with search filtering and copy-to-clipboard.
 * Receives a pre-sanitised list from the server component — no internal
 * IDs, IPs, owner info, or node names ever reach the client.
 */
export function ServerDirectoryList({ servers }: { servers: DirectoryServer[] }) {
  const [search, setSearch] = useState("");
  const [copied, setCopied] = useState<string | null>(null);

  const q = search.toLowerCase().trim();
  const filtered = q
    ? servers.filter(
        (s) =>
          s.name.toLowerCase().includes(q) ||
          s.description?.toLowerCase().includes(q) ||
          s.gameLabel.toLowerCase().includes(q) ||
          s.variant?.toLowerCase().includes(q),
      )
    : servers;

  function copyAddress(addr: string) {
    navigator.clipboard.writeText(addr).then(() => {
      setCopied(addr);
      setTimeout(() => setCopied(null), 2000);
    });
  }

  return (
    <div>
      {/* Search bar */}
      <div className="mx-auto mb-8 max-w-xl">
        <div className="relative">
          <svg
            className="pointer-events-none absolute left-3.5 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-500"
            fill="none"
            viewBox="0 0 24 24"
            strokeWidth={2}
            stroke="currentColor"
          >
            <path strokeLinecap="round" strokeLinejoin="round" d="m21 21-5.197-5.197m0 0A7.5 7.5 0 1 0 5.196 5.196a7.5 7.5 0 0 0 10.607 10.607Z" />
          </svg>
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search servers by name, description, or game..."
            className="w-full rounded-2xl border border-white/[0.08] bg-navy-900/60 py-3 pl-10 pr-4 text-sm text-slate-200 placeholder:text-slate-500 backdrop-blur-sm focus:border-brand-500/40 focus:outline-none focus:ring-1 focus:ring-brand-500/30"
          />
        </div>
      </div>

      {/* Results count */}
      <div className="mb-4 flex items-center justify-between">
        <p className="text-sm text-slate-400">
          {filtered.length === 0
            ? "No servers found"
            : `${filtered.length} server${filtered.length === 1 ? "" : "s"}`}
        </p>
        {q && (
          <button
            onClick={() => setSearch("")}
            className="text-xs text-brand-300 hover:text-brand-200"
          >
            Clear search
          </button>
        )}
      </div>

      {/* Server grid */}
      {filtered.length > 0 ? (
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {filtered.map((s) => (
            <div
              key={s.key}
              className="group relative flex flex-col rounded-2xl border border-white/[0.07] bg-navy-900/50 p-5 backdrop-blur-sm transition-colors hover:border-white/[0.12] hover:bg-navy-900/70"
            >
              {/* Header row */}
              <div className="flex items-start justify-between gap-3">
                <div className="min-w-0 flex-1">
                  <div className="flex items-center gap-2">
                    <span className="inline-block h-2 w-2 flex-none rounded-full bg-emerald-400" title="Online" />
                    <h3 className="truncate font-semibold text-white" title={s.name}>
                      {s.name}
                    </h3>
                  </div>
                </div>
                {/* Badges */}
                <div className="flex flex-none items-center gap-1.5">
                  {s.isFree && (
                    <span className="rounded-full border border-brand-500/25 bg-brand-500/10 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-brand-300">
                      Free
                    </span>
                  )}
                </div>
              </div>

              {/* Description */}
              {s.description ? (
                <p className="mt-2.5 line-clamp-2 text-sm text-slate-400">{s.description}</p>
              ) : (
                <p className="mt-2.5 text-sm italic text-slate-600">No description</p>
              )}

              {/* Meta row */}
              <div className="mt-auto flex flex-wrap items-center gap-2 pt-4 text-xs text-slate-500">
                <span className="inline-flex items-center gap-1 rounded-full border border-white/[0.08] bg-white/[0.03] px-2 py-0.5 text-[11px] font-medium text-slate-400">
                  {s.gameLabel}
                </span>
                {s.variant && (
                  <span className="inline-flex items-center gap-1 rounded-full border border-white/[0.08] bg-white/[0.03] px-2 py-0.5 text-[11px] font-medium text-slate-400">
                    {s.variant}
                  </span>
                )}
                {s.maxPlayers != null && (
                  <span className="text-slate-500">{s.maxPlayers} slots</span>
                )}
              </div>

              {/* Connect row */}
              <div className="mt-3 flex items-center gap-2 border-t border-white/[0.06] pt-3">
                <code className="min-w-0 flex-1 truncate rounded-lg border border-white/[0.06] bg-navy-950/60 px-2.5 py-1.5 font-mono text-xs text-slate-300">
                  {s.connectAddress}
                </code>
                <button
                  onClick={() => copyAddress(s.connectAddress)}
                  className="flex flex-none items-center gap-1.5 rounded-lg border border-brand-500/25 bg-brand-500/10 px-3 py-1.5 text-xs font-medium text-brand-200 transition hover:bg-brand-500/20"
                >
                  {copied === s.connectAddress ? (
                    <>
                      <CheckIcon />
                      Copied
                    </>
                  ) : (
                    <>
                      <CopyIcon />
                      Copy
                    </>
                  )}
                </button>
              </div>
            </div>
          ))}
        </div>
      ) : (
        <div className="rounded-2xl border border-white/[0.06] bg-navy-900/30 py-16 text-center">
          <p className="text-lg font-semibold text-slate-300">No servers listed yet</p>
          <p className="mt-2 text-sm text-slate-500">
            Be the first to list your server in the directory.
          </p>
        </div>
      )}
    </div>
  );
}

function CopyIcon() {
  return (
    <svg className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor">
      <path
        strokeLinecap="round"
        strokeLinejoin="round"
        d="M15.666 3.888A2.25 2.25 0 0 0 13.5 2.25h-3c-1.03 0-1.9.693-2.166 1.638m7.332 0c.055.194.084.4.084.612v0a.75.75 0 0 1-.75.75H9.75a.75.75 0 0 1-.75-.75v0c0-.212.03-.418.084-.612m7.332 0c.646.049 1.288.11 1.927.184 1.1.128 1.907 1.077 1.907 2.185V19.5a2.25 2.25 0 0 1-2.25 2.25H6.75A2.25 2.25 0 0 1 4.5 19.5V6.257c0-1.108.806-2.057 1.907-2.185a48.208 48.208 0 0 1 1.927-.184"
      />
    </svg>
  );
}

function CheckIcon() {
  return (
    <svg className="h-3.5 w-3.5 text-emerald-400" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor">
      <path strokeLinecap="round" strokeLinejoin="round" d="m4.5 12.75 6 6 9-13.5" />
    </svg>
  );
}
